// add returns the sum of a and b.
func add(a, b int) int {
	return a + b
}

// factorial returns n! for a small non-negative integer n.
func factorial(n int) int {
	result := 1
	for i := 2; i <= n; i++ {
		result *= i
	}
	return result
}

