package main

import "testing"

func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestFactorial(t *testing.T) {
	cases := []struct {
		n    int
		want int
	}{
		{n: 0, want: 1},
		{n: 1, want: 1},
		{n: 5, want: 120},
		{n: 10, want: 3628800},
	}
	for _, tc := range cases {
		if got := factorial(tc.n); got != tc.want {
			t.Fatalf("factorial(%d) = %d, want %d", tc.n, got, tc.want)
		}
	}
}

